+  <script>
+    (() => {
+      const viewport = document.querySelector('.map-viewport');
+      if (!viewport) return;
+
+      // Start centered on the map.
+      viewport.scrollLeft = (viewport.scrollWidth - viewport.clientWidth) / 2;
+      viewport.scrollTop = (viewport.scrollHeight - viewport.clientHeight) / 2;
+
+      // Native scroll-axis-lock: none handles free 2D panning where supported.
+      if (window.CSS?.supports?.('scroll-axis-lock', 'none')) return;
+
+      // Fallback: apply raw, unlocked 2D deltas directly to scrollLeft/scrollTop.
+      const LINE_PX = 16;
+      viewport.addEventListener('wheel', (e) => {
+        if (e.ctrlKey) return; // keep pinch / ctrl+wheel page zoom
+        e.preventDefault();
+        const scale = e.deltaMode === 1 ? LINE_PX : e.deltaMode === 2 ? viewport.clientHeight : 1;
+        viewport.scrollLeft += e.deltaX * scale;
+        viewport.scrollTop += e.deltaY * scale;
+      }, { passive: false });
+
+      let last = null;
+      viewport.addEventListener('pointerdown', (e) => {
+        const rect = viewport.getBoundingClientRect();
+        if (
+          !e.isPrimary || e.button !== 0 ||
+          e.clientX - rect.left - viewport.clientLeft >= viewport.clientWidth ||
+          e.clientY - rect.top - viewport.clientTop >= viewport.clientHeight
+        ) return; // ignore secondary buttons and native scrollbar clicks
+        last = { x: e.clientX, y: e.clientY };
+        viewport.setPointerCapture(e.pointerId);
+        viewport.classList.add('is-panning');
+      });
+
+      viewport.addEventListener('pointermove', (e) => {
+        if (!last) return;
+        viewport.scrollLeft -= e.clientX - last.x;
+        viewport.scrollTop -= e.clientY - last.y;
+        last = { x: e.clientX, y: e.clientY };
+      });
+
+      const endPan = () => {
+        last = null;
+        viewport.classList.remove('is-panning');
+      };
+      viewport.addEventListener('pointerup', endPan);
+      viewport.addEventListener('pointercancel', endPan);
+    })();
+  </script>
+
 </body>

