+:root {
+  --primary: #4e342e;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+  --surface: #ffffff;
+  color-scheme: light;
+}
+
+/* Dark theme, applied by /js/theme.js before first render */
+:root[data-theme="dark"] {
+  --primary: #2b1d19;
+  --secondary: #3a2c27;
+  --text: #efe6e2;
+  --light: #1c1412;
+  --surface: #2a201d;
+  color-scheme: dark;
+}
+
+/* ---------- Cross-document view transitions ---------- */
+@view-transition {
+  navigation: auto;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  @view-transition {
+    navigation: none;
+  }
+}
+
+/* Keep the site header fixed in place while the page content transitions */
+nav {
+  view-transition-name: site-header;
+}
+
+::view-transition-group(site-header) {
+  animation-duration: 0s;
+}
+
+::view-transition-old(root) {
+  animation: 0.25s ease-in both page-fade-out;
+}
+
+::view-transition-new(root) {
+  animation: 0.35s ease-out 0.05s both page-fade-in;
+}
+
+@keyframes page-fade-out {
+  to { opacity: 0; transform: translateY(-12px); }
+}
+
+@keyframes page-fade-in {
+  from { opacity: 0; transform: translateY(16px); }
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+}
+
+/* Navigation */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
