diff --git a/js/theme.js b/js/theme.js
new file mode 100644
index 0000000..56e6c44
--- /dev/null
+++ b/js/theme.js
@@ -0,0 +1,31 @@
+// Applies the saved (or system-preferred) theme before first render so the
+// page — and any view transition snapshot of it — never flashes the wrong theme.
+(() => {
+  const root = document.documentElement;
+  const stored = localStorage.getItem('theme');
+  const theme = stored ?? (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
+  root.dataset.theme = theme;
+
+  const initToggle = () => {
+    const toggle = document.querySelector('.theme-toggle');
+    if (!toggle) return;
+    const sync = () => {
+      const dark = root.dataset.theme === 'dark';
+      toggle.setAttribute('aria-pressed', String(dark));
+      toggle.textContent = dark ? 'Light mode' : 'Dark mode';
+    };
+    sync();
+    toggle.addEventListener('click', () => {
+      root.dataset.theme = root.dataset.theme === 'dark' ? 'light' : 'dark';
+      localStorage.setItem('theme', root.dataset.theme);
+      sync();
+    });
+  };
+
+  // This script loads async, so the DOM may already be parsed when it runs.
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initToggle);
+  } else {
+    initToggle();
+  }
+})();
