+        const li = document.createElement('li');
+        const dot = document.createElement('span');
+        dot.style.background = `rgb(${rgb.map((c) => Math.round(c ** (1 / 2.2) * 255)).join(' ')})`;
+        li.append(dot, name);
+        return li;
+      }));
+    }
+
+    let worker;
+    let renderId = 0;
+
+    function render(colors) {
+      // Restart the worker so a new click cancels any render still in progress.
+      worker?.terminate();
+      worker = new Worker(new URL('./smallpt-worker.js', import.meta.url), { type: 'module' });
+
+      const id = ++renderId;
+      const spp = Number(sppSelect.value);
+      const { width, height } = canvas;
+      showSwatches(colors);
+      progress.value = 0;
+      status.textContent = `Rendering at ${spp} samples/pixel…`;
+
+      worker.onmessage = ({ data }) => {
+        if (data.id !== id) return;
+        ctx.putImageData(new ImageData(data.pixels, data.width, data.height), 0, 0);
+        progress.value = data.progress;
+        if (data.progress >= 1) {
+          status.textContent = `Rendered ${width}×${height} at ${spp} samples/pixel in ${(data.elapsed / 1000).toFixed(1)} s`;
+        }
+      };
+      worker.onerror = (event) => {
+        status.textContent = `Renderer failed: ${event.message ?? 'unknown error'}`;
+      };
+      worker.postMessage({
+        id,
+        width,
+        height,
+        spp,
+        colors: colors.map(({ index, rgb }) => ({ index, rgb })),
+      });
+    }
+
+    button.addEventListener('click', () => render(randomColors()));
+    render(SPHERES); // First render: smallpt's original scene.
+  </script>
 </body>

 </html>
