+#!/bin/sh
+# Compile smallpt to an ES6 WebAssembly module for use inside a module Web Worker.
+set -e
+cd "$(dirname "$0")"
+mkdir -p ../wasm
+em++ -c smallpt.cpp -o smallpt.o -O3 -flto -fno-exceptions -Wall -Werror
+# Link with emcc: nothing needs libc++, and skipping it avoids a libc++abi LTO link bug.
+emcc smallpt.o -o ../wasm/smallpt.js \
+  -O3 -flto \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_begin_render,_render_rows,_set_sphere_color,_reset_sphere_colors,_sphere_count \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+rm -f smallpt.o
