+
+// ---------------------------------------------------------------------------
+// WebAssembly API (replaces the original main()).
+// ---------------------------------------------------------------------------
+static const int NSPHERES = sizeof(spheres)/sizeof(Sphere);
+static Sphere defaults[NSPHERES] = {
+  spheres[0], spheres[1], spheres[2], spheres[3], spheres[4],
+  spheres[5], spheres[6], spheres[7], spheres[8]
+};
+static int w = 0, h = 0, samps = 1;
+static Vec *c = nullptr;              // accumulated linear color, as in main()
+static unsigned char *rgba = nullptr; // 8-bit RGBA, top row first, for <canvas>
+static Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+static Vec cx, cy;
+
+extern "C" {
+
+int sphere_count() { return NSPHERES; }
+
+void set_sphere_color(int i, double r, double g, double b) {
+  if (i >= 0 && i < NSPHERES) spheres[i].c = Vec(r, g, b);
+}
+
+void reset_sphere_colors() {
+  for (int i = 0; i < NSPHERES; i++) spheres[i].c = defaults[i].c;
+}
+
+// Allocate buffers for a w_ x h_ image at spp samples per pixel.
+// Returns a pointer to the RGBA output (w_*h_*4 bytes).
+unsigned char *begin_render(int w_, int h_, int spp) {
+  free(c); free(rgba);   // malloc/free: avoids pulling in libc++abi
+  w = w_; h = h_; samps = spp/4 > 0 ? spp/4 : 1;
+  c = (Vec*)malloc(sizeof(Vec)*w*h);
+  rgba = (unsigned char*)malloc(w*h*4);
+  for (int i = 0; i < w*h; i++) c[i] = Vec();
+  for (int i = 0; i < w*h*4; i++) rgba[i] = (i & 3) == 3 ? 255 : 0;
+  cx = Vec(w*.5135/h); cy = (cx%cam.d).norm()*.5135;
+  return rgba;
+}
+
+// Render image rows [y0, y1) -- the body of the original main() loop.
+void render_rows(int y0, int y1) {
+  Vec r;
+  for (int y=y0; y<y1 && y<h; y++){                // Loop over image rows
+    for (unsigned short x=0, Xi[3]={0,0,(unsigned short)(y*y*y)}; x<w; x++) // cols
+      for (int sy=0, i=(h-y-1)*w+x; sy<2; sy++)     // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++, r=Vec()){        // 2x2 subpixel cols
+          for (int s=0; s<samps; s++){
+            double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+            double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+            Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                    cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+          } // Camera rays are pushed ^^^^^ forward to start in interior
+          c[i] = c[i] + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+    for (int x=0; x<w; x++) {                       // Write 8-bit pixels
+      int i = (h-y-1)*w+x;
+      rgba[i*4+0] = toInt(c[i].x);
+      rgba[i*4+1] = toInt(c[i].y);
+      rgba[i*4+2] = toInt(c[i].z);
+    }
+  }
+}
+
+} // extern "C"
