+#!/usr/bin/env sh
+# Builds smallpt to WebAssembly. Requires Emscripten (emcc/em++) on PATH.
+set -eu
+cd "$(dirname "$0")"
+OUT=../public/smallpt
+mkdir -p "$OUT"
+em++ -c smallpt.cpp -o smallpt.o -O3 -Wall -Werror
+emcc smallpt.o -o "$OUT/smallpt.js" \
+  -O3 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_begin_render,_render_rows,_set_sphere_color,_reset_sphere_colors,_sphere_count \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+rm -f smallpt.o
