+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
+    :host {
+      display: block;
+      position: relative;
+      background: white;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+      overflow: hidden;
+      transition: transform 0.2s, box-shadow 0.2s, opacity 0.2s;
+    }
+    :host(:hover) {
+      transform: translateY(-2px);
+      box-shadow: 0 6px 14px rgba(0, 0, 0, 0.12);
+    }
+    :host([hidden]) { display: none; }
+    :host([sold-out]) { opacity: 0.6; }
+    :host([sold-out]:hover) { transform: none; }
+
+    img {
+      display: block;
+      width: 100%;
+      aspect-ratio: 4 / 3;
+      object-fit: cover;
+    }
+    img[hidden] { display: none; }
+
+    .body { padding: 20px; }
+
+    .badge {
+      position: absolute;
+      top: 12px;
+      left: 12px;
+      background: var(--accent, #ffab40);
+      color: var(--text, #3e2723);
+      font-size: 0.75rem;
+      font-weight: bold;
+      padding: 3px 10px;
+      border-radius: 999px;
+      text-transform: uppercase;
+      letter-spacing: 0.5px;
+    }
+    .badge[hidden], .price[hidden], .strength[hidden] { display: none; }
+
+    h3 {
+      margin: 0 0 10px;
+      color: var(--primary, #4e342e);
+    }
+
+    .meta {
+      display: flex;
+      justify-content: center;
+      align-items: center;
+      gap: 12px;
+      margin-bottom: 10px;
+      font-size: 0.9rem;
+    }
+    .price { font-weight: bold; }
+    .strength { letter-spacing: 2px; }
+    .strength .off { opacity: 0.25; }
+
+    .btn {
+      display: inline-block;
+      background: var(--primary, #4e342e);
+      color: white;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+    .btn:hover { background: #3e2723; }
+    .btn[aria-disabled="true"] {
+      background: #9e9e9e;
+      cursor: not-allowed;
+      pointer-events: none;
+    }
+  </style>
+  <span class="badge" part="badge" hidden>Seasonal Pick</span>
+  <img part="image" alt="" hidden>
+  <div class="body" part="body">
+    <h3 part="name"></h3>
+    <div class="meta">
+      <span class="price" part="price" hidden></span>
+      <span class="strength" part="strength" role="img" hidden></span>
+    </div>
+    <p part="description"><slot></slot></p>
+    <a class="btn" part="button">View Details</a>
+  </div>
