--- /dev/null
+++ b/js/signing-core.js
@@ -0,0 +1,438 @@
+/**
+ * Daily Grind — signed document core.
+ *
+ * Pure crypto + envelope logic (no DOM, no storage) so it can be unit tested
+ * in Node as well as used in the browser.
+ *
+ * Supported signature algorithms:
+ *   - ECDSA-P256  (WebCrypto, classical, widely supported)
+ *   - Ed25519     (WebCrypto, classical, modern browsers)
+ *   - ML-DSA-65   (FIPS 204, post-quantum, via vendored @noble/post-quantum)
+ *
+ * Token format:  "DG1." + base64url(UTF-8 JSON envelope)
+ * Envelope:      { v, typ, alg, kid, pub, payload, sig }
+ * Signed bytes:  UTF-8( DOMAIN + "\n" + canonicalJSON({ v, typ, alg, kid, payload }) )
+ *
+ * The algorithm, key id and document type are all covered by the signature,
+ * preventing algorithm-substitution and receipt/voucher type-confusion attacks.
+ */
+
+export const TOKEN_PREFIX = 'DG1.';
+export const PUBKEY_PREFIX = 'DGPK1.';
+export const DOMAIN = 'daily-grind/signed-document/v1';
+export const ENVELOPE_VERSION = 1;
+export const DOC_TYPES = Object.freeze(['receipt', 'voucher']);
+const MAX_TOKEN_LENGTH = 64 * 1024;
+
+const subtle = globalThis.crypto.subtle;
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+/* ------------------------------------------------------------------ */
+/* Encoding helpers                                                    */
+/* ------------------------------------------------------------------ */
+
+export function bytesToB64url(bytes) {
+  let bin = '';
+  const chunk = 0x8000;
+  for (let i = 0; i < bytes.length; i += chunk) {
+    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function b64urlToBytes(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Invalid base64url data');
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+/**
+ * Deterministic JSON serialisation: object keys sorted lexicographically,
+ * no whitespace. Only plain JSON values are allowed.
+ */
+export function canonicalize(value) {
+  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
+    return JSON.stringify(value);
+  }
+  if (typeof value === 'number') {
+    if (!Number.isFinite(value)) throw new Error('Non-finite numbers cannot be signed');
+    return JSON.stringify(value);
+  }
+  if (Array.isArray(value)) {
+    return '[' + value.map(canonicalize).join(',') + ']';
+  }
+  if (typeof value === 'object') {
+    const proto = Object.getPrototypeOf(value);
+    if (proto !== Object.prototype && proto !== null) {
+      throw new Error('Only plain objects can be signed');
+    }
+    const keys = Object.keys(value).sort();
+    return '{' + keys.map((k) => {
+      if (value[k] === undefined) throw new Error(`Field "${k}" is undefined`);
+      return JSON.stringify(k) + ':' + canonicalize(value[k]);
+    }).join(',') + '}';
+  }
+  throw new Error(`Unsupported value type: ${typeof value}`);
+}
+
+/* ------------------------------------------------------------------ */
+/* Algorithms                                                          */
+/* ------------------------------------------------------------------ */
+
+let mlDsaModule = null;
+async function loadMlDsa() {
+  if (!mlDsaModule) {
+    mlDsaModule = import(new URL('../vendor/noble-ml-dsa-0.7.1.mjs', import.meta.url).href)
+      .then((m) => m.ml_dsa65)
+      .catch((err) => { mlDsaModule = null; throw err; });
+  }
+  return mlDsaModule;
+}
+
+const ML_DSA_CONTEXT = enc.encode(DOMAIN);
+
+const ALGS = {
+  'ECDSA-P256': {
+    label: 'ECDSA P-256 (classical)',
+    postQuantum: false,
+    async generate() {
+      const kp = await subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']);
+      const pub = new Uint8Array(await subtle.exportKey('spki', kp.publicKey));
+      return { publicKey: pub, privateKey: kp.privateKey };
+    },
+    async sign(privateKey, msg) {
+      return new Uint8Array(await subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, privateKey, msg));
+    },
+    async verify(pub, sig, msg) {
+      const key = await subtle.importKey('spki', pub, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']);
+      return subtle.verify({ name: 'ECDSA', hash: 'SHA-256' }, key, sig, msg);
+    },
+    sigLength: 64,
+  },
+  Ed25519: {
+    label: 'Ed25519 (classical)',
+    postQuantum: false,
+    async generate() {
+      const kp = await subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify']);
+      const pub = new Uint8Array(await subtle.exportKey('raw', kp.publicKey));
+      return { publicKey: pub, privateKey: kp.privateKey };
+    },
+    async sign(privateKey, msg) {
+      return new Uint8Array(await subtle.sign({ name: 'Ed25519' }, privateKey, msg));
+    },
+    async verify(pub, sig, msg) {
+      if (pub.length !== 32) return false;
+      const key = await subtle.importKey('raw', pub, { name: 'Ed25519' }, false, ['verify']);
+      return subtle.verify({ name: 'Ed25519' }, key, sig, msg);
+    },
+    sigLength: 64,
+  },
+  'ML-DSA-65': {
+    label: 'ML-DSA-65 (post-quantum, FIPS 204)',
+    postQuantum: true,
+    async generate() {
+      const ml = await loadMlDsa();
+      const seed = globalThis.crypto.getRandomValues(new Uint8Array(32));
+      const { publicKey, secretKey } = ml.keygen(seed);
+      seed.fill(0);
+      return { publicKey, privateKey: secretKey };
+    },
+    async sign(secretKey, msg) {
+      const ml = await loadMlDsa();
+      return ml.sign(msg, secretKey, { context: ML_DSA_CONTEXT });
+    },
+    async verify(pub, sig, msg) {
+      const ml = await loadMlDsa();
+      if (pub.length !== ml.lengths.publicKey) return false;
+      return ml.verify(sig, msg, pub, { context: ML_DSA_CONTEXT });
+    },
+    sigLength: 3309,
+  },
+};
+
+export const ALGORITHMS = Object.freeze(
+  Object.fromEntries(Object.entries(ALGS).map(([id, a]) => [id, Object.freeze({ id, label: a.label, postQuantum: a.postQuantum })])),
+);
+
+function getAlg(alg) {
+  if (!Object.prototype.hasOwnProperty.call(ALGS, alg)) throw new Error(`Unsupported algorithm: ${alg}`);
+  return ALGS[alg];
+}
+
+/** Detect which algorithms work in the current runtime. */
+export async function detectSupport() {
+  const result = {};
+  for (const id of Object.keys(ALGS)) {
+    try {
+      if (id === 'ML-DSA-65') await loadMlDsa();
+      else if (id === 'Ed25519') await subtle.generateKey({ name: 'Ed25519' }, false, ['sign']);
+      result[id] = true;
+    } catch {
+      result[id] = false;
+    }
+  }
+  return result;
+}
+
+/* ------------------------------------------------------------------ */
+/* Keys                                                                */
+/* ------------------------------------------------------------------ */
+
+/** Key id: base64url of first 16 bytes of SHA-256(alg || 0x00 || publicKey). */
+export async function keyId(alg, publicKey) {
+  const algBytes = enc.encode(alg);
+  const data = new Uint8Array(algBytes.length + 1 + publicKey.length);
+  data.set(algBytes, 0);
+  data.set(publicKey, algBytes.length + 1);
+  const digest = new Uint8Array(await subtle.digest('SHA-256', data));
+  return bytesToB64url(digest.subarray(0, 16));
+}
+
+/** Human-friendly fingerprint for out-of-band comparison, e.g. "A1B2-C3D4-...". */
+export function formatFingerprint(kid) {
+  const hex = Array.from(b64urlToBytes(kid), (b) => b.toString(16).padStart(2, '0')).join('').toUpperCase();
+  return hex.match(/.{1,4}/g).join('-');
+}
+
+/**
+ * Generate a signing key pair. WebCrypto private keys are non-extractable.
+ * Returns { alg, kid, publicKey: Uint8Array, privateKey: CryptoKey|Uint8Array }.
+ */
+export async function generateKeyPair(alg) {
+  const { publicKey, privateKey } = await getAlg(alg).generate();
+  return { alg, kid: await keyId(alg, publicKey), publicKey, privateKey };
+}
+
+export function exportPublicKey({ alg, publicKey, label }) {
+  const body = { v: 1, alg, pub: bytesToB64url(publicKey) };
+  if (label) body.label = String(label).slice(0, 80);
+  return PUBKEY_PREFIX + bytesToB64url(enc.encode(canonicalize(body)));
+}
+
+export async function importPublicKey(str) {
+  str = String(str).trim();
+  if (!str.startsWith(PUBKEY_PREFIX) || str.length > MAX_TOKEN_LENGTH) throw new Error('Not a Daily Grind public key');
+  let body;
+  try {
+    body = JSON.parse(dec.decode(b64urlToBytes(str.slice(PUBKEY_PREFIX.length))));
+  } catch {
+    throw new Error('Public key is malformed');
+  }
+  if (!body || body.v !== 1 || typeof body.pub !== 'string') throw new Error('Public key is malformed');
+  getAlg(body.alg);
+  const publicKey = b64urlToBytes(body.pub);
+  return {
+    alg: body.alg,
+    publicKey,
+    kid: await keyId(body.alg, publicKey),
+    label: typeof body.label === 'string' ? body.label.slice(0, 80) : '',
+  };
+}
+
+/* ------------------------------------------------------------------ */
+/* Payload validation                                                  */
+/* ------------------------------------------------------------------ */
+
+const isInt = (n, min = 0, max = 1e9) => Number.isSafeInteger(n) && n >= min && n <= max;
+const isStr = (s, max = 200, min = 0) => typeof s === 'string' && s.length >= min && s.length <= max;
+const isIsoDate = (s) => typeof s === 'string' && s.length <= 40 && !Number.isNaN(Date.parse(s));
+
+/** Returns a list of structural problems with the payload (empty = OK). */
+export function validatePayload(typ, p) {
+  const errs = [];
+  if (!p || typeof p !== 'object' || Array.isArray(p)) return ['Payload must be an object'];
+  if (!isIsoDate(p.issuedAt)) errs.push('issuedAt must be an ISO date');
+  if (p.currency !== 'USD') errs.push('currency must be USD');
+  if (typ === 'receipt') {
+    if (!isStr(p.id, 40, 1)) errs.push('Receipt id missing');
+    if (!isStr(p.store, 100, 1)) errs.push('Store missing');
+    if (!Array.isArray(p.items) || p.items.length === 0 || p.items.length > 50) {
+      errs.push('Receipt must contain 1–50 items');
+    } else {
+      p.items.forEach((it, i) => {
+        if (!it || !isStr(it.name, 100, 1) || !isInt(it.qty, 1, 99) || !isInt(it.unitCents, 0, 100000)) {
+          errs.push(`Item #${i + 1} is malformed`);
+        }
+      });
+    }
+    for (const f of ['subtotalCents', 'taxCents', 'totalCents']) {
+      if (!isInt(p[f], 0, 1e8)) errs.push(`${f} must be a non-negative integer`);
+    }
+  } else if (typ === 'voucher') {
+    if (!isStr(p.code, 40, 1)) errs.push('Voucher code missing');
+    if (!isStr(p.recipient, 100, 1)) errs.push('Recipient missing');
+    if (!isStr(p.from, 100)) errs.push('From is malformed');
+    if (!isStr(p.message, 500)) errs.push('Message is malformed');
+    if (!isInt(p.amountCents, 100, 50000)) errs.push('Voucher amount must be between $1 and $500');
+    if (!isIsoDate(p.expiresAt)) errs.push('expiresAt must be an ISO date');
+  } else {
+    errs.push(`Unknown document type: ${typ}`);
+  }
+  return errs;
+}
+
+/** Business-rule checks run after the signature is verified. */
+export function businessChecks(typ, p, now = new Date()) {
+  const warnings = [];
+  if (typ === 'receipt') {
+    const sum = p.items.reduce((acc, it) => acc + it.qty * it.unitCents, 0);
+    if (sum !== p.subtotalCents) warnings.push('Line items do not add up to the subtotal');
+    if (p.subtotalCents + p.taxCents !== p.totalCents) warnings.push('Subtotal plus tax does not equal total');
+  } else if (typ === 'voucher') {
+    if (Date.parse(p.expiresAt) < now.getTime()) warnings.push('Voucher has expired');
+    if (Date.parse(p.expiresAt) <= Date.parse(p.issuedAt)) warnings.push('Voucher expires before it was issued');
+  }
+  if (Date.parse(p.issuedAt) > now.getTime() + 5 * 60 * 1000) warnings.push('Issue date is in the future');
+  return warnings;
+}
+
+/* ------------------------------------------------------------------ */
+/* Sign / verify                                                       */
+/* ------------------------------------------------------------------ */
+
+function signingInput({ typ, alg, kid, payload }) {
+  return enc.encode(DOMAIN + '\n' + canonicalize({ v: ENVELOPE_VERSION, typ, alg, kid, payload }));
+}
+
+/**
+ * Sign a document. `key` is { alg, kid, publicKey, privateKey }.
+ * Returns { envelope, token }.
+ */
+export async function signDocument(key, typ, payload) {
+  if (!DOC_TYPES.includes(typ)) throw new Error(`Unknown document type: ${typ}`);
+  const errs = validatePayload(typ, payload);
+  if (errs.length) throw new Error(errs.join('; '));
+  // Normalise payload through canonical JSON so what we sign is exactly what we emit.
+  const normalized = JSON.parse(canonicalize(payload));
+  const header = { typ, alg: key.alg, kid: key.kid, payload: normalized };
+  const sig = await getAlg(key.alg).sign(key.privateKey, signingInput(header));
+  const envelope = {
+    v: ENVELOPE_VERSION,
+    ...header,
+    pub: bytesToB64url(key.publicKey),
+    sig: bytesToB64url(sig),
+  };
+  return { envelope, token: encodeToken(envelope) };
+}
+
+export function encodeToken(envelope) {
+  return TOKEN_PREFIX + bytesToB64url(enc.encode(canonicalize(envelope)));
+}
+
+/** Accepts either a "DG1." token or the raw JSON envelope. */
+export function decodeToken(input) {
+  const str = String(input).trim();
+  if (str.length > MAX_TOKEN_LENGTH) throw new Error('Token is too large');
+  let json;
+  if (str.startsWith(TOKEN_PREFIX)) {
+    try {
+      json = dec.decode(b64urlToBytes(str.slice(TOKEN_PREFIX.length).replace(/\s+/g, '')));
+    } catch {
+      throw new Error('Token is not valid base64url / UTF-8');
+    }
+  } else if (str.startsWith('{')) {
+    json = str;
+  } else {
+    throw new Error(`Expected a token starting with "${TOKEN_PREFIX}" or a JSON envelope`);
+  }
+  let env;
+  try {
+    env = JSON.parse(json);
+  } catch {
+    throw new Error('Token does not contain valid JSON');
+  }
+  if (!env || typeof env !== 'object' || Array.isArray(env)) throw new Error('Envelope must be an object');
+  return env;
+}
+
+/**
+ * Verify an envelope or token.
+ *
+ * @param {object|string} input  envelope or token
+ * @param {Map<string, {alg:string, label?:string}>} trustedKeys  kid -> info
+ * @returns {Promise<{
+ *   status: 'trusted'|'untrusted'|'invalid',
+ *   signatureValid: boolean, trusted: boolean,
+ *   errors: string[], warnings: string[],
+ *   envelope?: object, signer?: object
+ * }>}
+ */
+export async function verifyDocument(input, trustedKeys = new Map(), now = new Date()) {
+  const result = { status: 'invalid', signatureValid: false, trusted: false, errors: [], warnings: [] };
+  let env;
+  try {
+    env = typeof input === 'string' ? decodeToken(input) : input;
+  } catch (e) {
+    result.errors.push(e.message);
+    return result;
+  }
+  result.envelope = env;
+
+  if (env.v !== ENVELOPE_VERSION) result.errors.push('Unsupported envelope version');
+  if (!DOC_TYPES.includes(env.typ)) result.errors.push('Unknown document type');
+  if (!Object.prototype.hasOwnProperty.call(ALGS, env.alg)) result.errors.push('Unsupported signature algorithm');
+  if (typeof env.kid !== 'string' || typeof env.pub !== 'string' || typeof env.sig !== 'string') {
+    result.errors.push('Envelope is missing kid, pub or sig');
+  }
+  if (result.errors.length) return result;
+
+  const payloadErrors = validatePayload(env.typ, env.payload);
+  if (payloadErrors.length) {
+    result.errors.push(...payloadErrors);
+    return result;
+  }
+
+  let pub;
+  let sig;
+  try {
+    pub = b64urlToBytes(env.pub);
+    sig = b64urlToBytes(env.sig);
+  } catch {
+    result.errors.push('Public key or signature is not valid base64url');
+    return result;
+  }
+
+  const expectedKid = await keyId(env.alg, pub);
+  if (expectedKid !== env.kid) {
+    result.errors.push('Key id does not match the embedded public key');
+    return result;
+  }
+
+  const alg = getAlg(env.alg);
+  if (sig.length !== alg.sigLength) {
+    result.errors.push('Signature has the wrong length');
+    return result;
+  }
+
+  let ok = false;
+  try {
+    ok = await alg.verify(pub, sig, signingInput(env));
+  } catch (e) {
+    result.errors.push(`Verification error: ${e.message}`);
+    return result;
+  }
+  if (!ok) {
+    result.errors.push('Signature does not match — the document was altered or signed by a different key');
+    return result;
+  }
+
+  result.signatureValid = true;
+  const trustedInfo = trustedKeys.get(env.kid);
+  result.trusted = Boolean(trustedInfo && trustedInfo.alg === env.alg);
+  result.signer = {
+    kid: env.kid,
+    alg: env.alg,
+    fingerprint: formatFingerprint(env.kid),
+    label: result.trusted ? trustedInfo.label || '' : '',
+    postQuantum: ALGS[env.alg].postQuantum,
+  };
+  result.warnings = businessChecks(env.typ, env.payload, now);
+  result.status = result.trusted ? 'trusted' : 'untrusted';
+  return result;
+}
diff --git a/js/signing-ui.js b/js/signing-ui.js
new file mode 100644
index 0000000..6c28162
--- /dev/null
+++ b/js/signing-ui.js
@@ -0,0 +1,552 @@
+/**
+ * Daily Grind — signing UI and key storage (IndexedDB).
+ *
+ * Keys never leave the browser. WebCrypto private keys (ECDSA / Ed25519) are
+ * stored as non-extractable CryptoKey objects; ML-DSA secret keys are stored
+ * as raw bytes (no WebCrypto support yet), scoped to this origin's IndexedDB.
+ *
+ * All untrusted document content is rendered with textContent only.
+ */
+import * as core from './signing-core.js';
+
+/* ------------------------------------------------------------------ */
+/* Storage                                                             */
+/* ------------------------------------------------------------------ */
+
+const DB_NAME = 'daily-grind-signing';
+const DB_VERSION = 1;
+const ACTIVE_KEY_PREF = 'dg-active-signing-kid';
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, DB_VERSION);
+    req.onupgradeneeded = () => {
+      const db = req.result;
+      if (!db.objectStoreNames.contains('keys')) db.createObjectStore('keys', { keyPath: 'kid' });
+      if (!db.objectStoreNames.contains('trusted')) db.createObjectStore('trusted', { keyPath: 'kid' });
+    };
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+let dbPromise;
+const db = () => (dbPromise ??= openDb());
+
+async function tx(store, mode, fn) {
+  const d = await db();
+  return new Promise((resolve, reject) => {
+    const t = d.transaction(store, mode);
+    const req = fn(t.objectStore(store));
+    t.oncomplete = () => resolve(req?.result);
+    t.onerror = () => reject(t.error);
+    t.onabort = () => reject(t.error);
+  });
+}
+
+const store = {
+  allKeys: () => tx('keys', 'readonly', (s) => s.getAll()),
+  putKey: (k) => tx('keys', 'readwrite', (s) => s.put(k)),
+  deleteKey: (kid) => tx('keys', 'readwrite', (s) => s.delete(kid)),
+  allTrusted: () => tx('trusted', 'readonly', (s) => s.getAll()),
+  putTrusted: (k) => tx('trusted', 'readwrite', (s) => s.put(k)),
+  deleteTrusted: (kid) => tx('trusted', 'readwrite', (s) => s.delete(kid)),
+};
+
+/* ------------------------------------------------------------------ */
+/* Helpers                                                             */
+/* ------------------------------------------------------------------ */
+
+const $ = (sel, root = document) => root.querySelector(sel);
+
+function el(tag, props = {}, ...children) {
+  const node = document.createElement(tag);
+  for (const [k, v] of Object.entries(props)) {
+    if (k === 'class') node.className = v;
+    else if (k === 'dataset') Object.assign(node.dataset, v);
+    else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
+    else if (v !== undefined && v !== null && v !== false) node.setAttribute(k, v === true ? '' : v);
+  }
+  for (const c of children.flat()) {
+    if (c !== null && c !== undefined && c !== false) node.append(c instanceof Node ? c : String(c));
+  }
+  return node;
+}
+
+const money = (cents) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100);
+const fmtDate = (iso) => new Date(iso).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+
+function randomCode(groups, len = 4) {
+  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I
+  const out = [];
+  for (let g = 0; g < groups; g++) {
+    const bytes = crypto.getRandomValues(new Uint8Array(len));
+    out.push(Array.from(bytes, (b) => alphabet[b % alphabet.length]).join(''));
+  }
+  return out.join('-');
+}
+
+function toast(msg, kind = 'info') {
+  const t = $('#sig-toast');
+  t.textContent = msg;
+  t.dataset.kind = kind;
+  t.hidden = false;
+  clearTimeout(toast.timer);
+  toast.timer = setTimeout(() => { t.hidden = true; }, 3500);
+}
+
+async function copyText(text) {
+  try {
+    await navigator.clipboard.writeText(text);
+    toast('Copied to clipboard', 'ok');
+  } catch {
+    toast('Copy failed — select the text and copy manually', 'warn');
+  }
+}
+
+function download(filename, text) {
+  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
+  const a = el('a', { href: url, download: filename });
+  document.body.append(a);
+  a.click();
+  a.remove();
+  setTimeout(() => URL.revokeObjectURL(url), 1000);
+}
+
+/* ------------------------------------------------------------------ */
+/* State                                                               */
+/* ------------------------------------------------------------------ */
+
+const MENU = [
+  { name: 'Maple Oat Latte', unitCents: 575 },
+  { name: 'Dark Roast Espresso', unitCents: 350 },
+  { name: 'Cold Brew', unitCents: 495 },
+  { name: 'Cappuccino', unitCents: 450 },
+  { name: 'Almond Croissant', unitCents: 395 },
+  { name: 'Blueberry Muffin', unitCents: 325 },
+];
+const TAX_RATE = 0.08;
+const STORE_NAME = 'The Daily Grind — Main Street';
+
+const state = {
+  keys: [],
+  trusted: [],
+  activeKid: localStorage.getItem(ACTIVE_KEY_PREF),
+  support: {},
+};
+
+async function trustMap() {
+  const m = new Map();
+  for (const k of state.keys) m.set(k.kid, { alg: k.alg, label: `${k.label} (this device)` });
+  for (const k of state.trusted) m.set(k.kid, { alg: k.alg, label: k.label });
+  return m;
+}
+
+function activeKey() {
+  return state.keys.find((k) => k.kid === state.activeKid) || null;
+}
+
+async function reload() {
+  [state.keys, state.trusted] = await Promise.all([store.allKeys(), store.allTrusted()]);
+  state.keys.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
+  if (!activeKey() && state.keys.length) setActive(state.keys[state.keys.length - 1].kid);
+  renderKeys();
+  renderTrusted();
+  renderActiveSigner();
+}
+
+function setActive(kid) {
+  state.activeKid = kid;
+  if (kid) localStorage.setItem(ACTIVE_KEY_PREF, kid);
+  else localStorage.removeItem(ACTIVE_KEY_PREF);
+}
+
+/* ------------------------------------------------------------------ */
+/* Keys panel                                                          */
+/* ------------------------------------------------------------------ */
+
+function algBadge(alg) {
+  const info = core.ALGORITHMS[alg];
+  return el('span', { class: `sig-badge ${info?.postQuantum ? 'pq' : 'classic'}` }, info?.postQuantum ? 'Quantum-resistant' : 'Classical');
+}
+
+function renderKeys() {
+  const list = $('#sig-key-list');
+  list.replaceChildren();
+  if (!state.keys.length) {
+    list.append(el('li', { class: 'sig-empty' }, 'No signing keys yet. Generate one to start issuing signed documents.'));
+    return;
+  }
+  for (const k of state.keys) {
+    const active = k.kid === state.activeKid;
+    list.append(el('li', { class: `sig-key ${active ? 'active' : ''}` },
+      el('div', { class: 'sig-key-head' },
+        el('strong', {}, k.label),
+        algBadge(k.alg),
+        active ? el('span', { class: 'sig-badge active' }, 'Active') : null,
+      ),
+      el('div', { class: 'sig-key-meta' }, `${k.alg} · created ${fmtDate(k.createdAt)}`),
+      el('code', { class: 'sig-fp', title: 'Key fingerprint' }, core.formatFingerprint(k.kid)),
+      el('div', { class: 'sig-key-actions' },
+        active ? null : el('button', { type: 'button', class: 'btn-sm', onclick: () => { setActive(k.kid); reload(); } }, 'Use for signing'),
+        el('button', { type: 'button', class: 'btn-sm', onclick: () => copyText(core.exportPublicKey(k)) }, 'Copy public key'),
+        el('button', {
+          type: 'button',
+          class: 'btn-sm danger',
+          onclick: async () => {
+            if (!confirm(`Delete signing key "${k.label}"? Documents it signed will no longer be trusted on this device.`)) return;
+            await store.deleteKey(k.kid);
+            if (active) setActive(null);
+            await reload();
+            toast('Key deleted');
+          },
+        }, 'Delete'),
+      ),
+    ));
+  }
+}
+
+async function onGenerate(e) {
+  e.preventDefault();
+  const form = e.currentTarget;
+  const alg = form.alg.value;
+  const label = form.label.value.trim() || `${alg} key`;
+  const btn = form.querySelector('button[type=submit]');
+  btn.disabled = true;
+  btn.textContent = 'Generating…';
+  try {
+    const kp = await core.generateKeyPair(alg);
+    await store.putKey({
+      kid: kp.kid,
+      alg,
+      label: label.slice(0, 60),
+      createdAt: new Date().toISOString(),
+      publicKey: kp.publicKey,
+      privateKey: kp.privateKey,
+    });
+    setActive(kp.kid);
+    form.label.value = '';
+    await reload();
+    toast(`Generated ${alg} key`, 'ok');
+  } catch (err) {
+    toast(`Key generation failed: ${err.message}`, 'error');
+  } finally {
+    btn.disabled = false;
+    btn.textContent = 'Generate key pair';
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Trusted keys                                                        */
+/* ------------------------------------------------------------------ */
+
+function renderTrusted() {
+  const list = $('#sig-trusted-list');
+  list.replaceChildren();
+  if (!state.trusted.length) {
+    list.append(el('li', { class: 'sig-empty' }, 'Your own keys are trusted automatically. Import other stores\' public keys here.'));
+    return;
+  }
+  for (const k of state.trusted) {
+    list.append(el('li', { class: 'sig-key' },
+      el('div', { class: 'sig-key-head' }, el('strong', {}, k.label || 'Unnamed signer'), algBadge(k.alg)),
+      el('code', { class: 'sig-fp' }, core.formatFingerprint(k.kid)),
+      el('div', { class: 'sig-key-actions' },
+        el('button', {
+          type: 'button',
+          class: 'btn-sm danger',
+          onclick: async () => { await store.deleteTrusted(k.kid); await reload(); },
+        }, 'Remove'),
+      ),
+    ));
+  }
+}
+
+async function addTrusted(imported, label) {
+  await store.putTrusted({
+    kid: imported.kid,
+    alg: imported.alg,
+    publicKey: imported.publicKey,
+    label: (label || imported.label || 'Imported signer').slice(0, 80),
+    addedAt: new Date().toISOString(),
+  });
+  await reload();
+}
+
+async function onImportTrusted(e) {
+  e.preventDefault();
+  const form = e.currentTarget;
+  try {
+    const imported = await core.importPublicKey(form.pubkey.value);
+    await addTrusted(imported, form.label.value.trim());
+    form.reset();
+    toast(`Trusted key ${core.formatFingerprint(imported.kid).slice(0, 19)}… added`, 'ok');
+  } catch (err) {
+    toast(err.message, 'error');
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Issue panel                                                         */
+/* ------------------------------------------------------------------ */
+
+function renderActiveSigner() {
+  const k = activeKey();
+  const box = $('#sig-active-signer');
+  box.replaceChildren(
+    k
+      ? el('span', {}, 'Signing as ', el('strong', {}, k.label), ' ', algBadge(k.alg))
+      : el('span', { class: 'sig-warn-text' }, 'Generate a signing key first.'),
+  );
+  for (const b of document.querySelectorAll('.sig-sign-btn')) b.disabled = !k;
+}
+
+function buildReceiptItems() {
+  const wrap = $('#sig-receipt-items');
+  for (const [i, item] of MENU.entries()) {
+    wrap.append(el('label', { class: 'sig-item-row' },
+      el('span', {}, item.name),
+      el('span', { class: 'sig-price' }, money(item.unitCents)),
+      el('input', { type: 'number', min: '0', max: '99', step: '1', value: i === 0 ? '1' : '0', name: `qty-${i}`, 'aria-label': `${item.name} quantity` }),
+    ));
+  }
+  wrap.addEventListener('input', updateReceiptTotals);
+  updateReceiptTotals();
+}
+
+function receiptFromForm() {
+  const form = $('#sig-receipt-form');
+  const items = [];
+  MENU.forEach((m, i) => {
+    const qty = Math.trunc(Number(form[`qty-${i}`].value));
+    if (qty > 0) items.push({ name: m.name, qty: Math.min(qty, 99), unitCents: m.unitCents });
+  });
+  const subtotalCents = items.reduce((a, it) => a + it.qty * it.unitCents, 0);
+  const taxCents = Math.round(subtotalCents * TAX_RATE);
+  return {
+    id: `R-${randomCode(2)}`,
+    store: STORE_NAME,
+    issuedAt: new Date().toISOString(),
+    currency: 'USD',
+    items,
+    subtotalCents,
+    taxCents,
+    totalCents: subtotalCents + taxCents,
+  };
+}
+
+function updateReceiptTotals() {
+  const r = receiptFromForm();
+  $('#sig-receipt-total').textContent = `Subtotal ${money(r.subtotalCents)} · Tax ${money(r.taxCents)} · Total ${money(r.totalCents)}`;
+}
+
+function voucherFromForm() {
+  const f = $('#sig-voucher-form');
+  const issued = new Date();
+  const months = Number(f.validity.value) || 12;
+  const expires = new Date(issued);
+  expires.setMonth(expires.getMonth() + months);
+  return {
+    code: `GV-${randomCode(3)}`,
+    recipient: f.recipient.value.trim(),
+    from: f.from.value.trim(),
+    message: f.message.value.trim(),
+    amountCents: Math.round(Number(f.amount.value) * 100),
+    currency: 'USD',
+    issuedAt: issued.toISOString(),
+    expiresAt: expires.toISOString(),
+  };
+}
+
+async function issue(typ, payload) {
+  const key = activeKey();
+  if (!key) return toast('Generate a signing key first', 'warn');
+  try {
+    const { token, envelope } = await core.signDocument(key, typ, payload);
+    showIssued(typ, token, envelope);
+    toast(`${typ === 'receipt' ? 'Receipt' : 'Voucher'} signed with ${key.alg}`, 'ok');
+  } catch (err) {
+    toast(`Could not sign: ${err.message}`, 'error');
+  }
+}
+
+function showIssued(typ, token, envelope) {
+  const out = $('#sig-issued');
+  out.hidden = false;
+  const docId = typ === 'receipt' ? envelope.payload.id : envelope.payload.code;
+  out.replaceChildren(
+    el('h4', {}, `Signed ${typ}: ${docId}`),
+    renderDocument(envelope.typ, envelope.payload),
+    el('label', { class: 'sig-label', for: 'sig-issued-token' }, `Signed token (${token.length.toLocaleString()} chars, ${envelope.alg})`),
+    el('textarea', { id: 'sig-issued-token', readonly: true, rows: '4', class: 'sig-token' }, token),
+    el('div', { class: 'sig-key-actions' },
+      el('button', { type: 'button', class: 'btn-sm', onclick: () => copyText(token) }, 'Copy token'),
+      el('button', {
+        type: 'button',
+        class: 'btn-sm',
+        onclick: () => download(`daily-grind-${typ}-${docId}.json`, JSON.stringify(envelope, null, 2)),
+      }, 'Download .json'),
+      el('button', {
+        type: 'button',
+        class: 'btn-sm',
+        onclick: () => { $('#sig-verify-input').value = token; runVerify(); $('#sig-verify').scrollIntoView({ behavior: 'smooth' }); },
+      }, 'Verify it'),
+    ),
+  );
+}
+
+/* ------------------------------------------------------------------ */
+/* Rendering documents (untrusted content → textContent only)          */
+/* ------------------------------------------------------------------ */
+
+function renderDocument(typ, p) {
+  if (typ === 'receipt') {
+    return el('div', { class: 'sig-doc receipt' },
+      el('div', { class: 'sig-doc-title' }, p.store),
+      el('div', { class: 'sig-doc-meta' }, `Receipt ${p.id} · ${fmtDate(p.issuedAt)}`),
+      el('table', {},
+        el('tbody', {}, p.items.map((it) => el('tr', {},
+          el('td', {}, `${it.qty} × ${it.name}`),
+          el('td', { class: 'num' }, money(it.qty * it.unitCents)),
+        ))),
+        el('tfoot', {},
+          el('tr', {}, el('td', {}, 'Subtotal'), el('td', { class: 'num' }, money(p.subtotalCents))),
+          el('tr', {}, el('td', {}, 'Tax'), el('td', { class: 'num' }, money(p.taxCents))),
+          el('tr', { class: 'total' }, el('td', {}, 'Total'), el('td', { class: 'num' }, money(p.totalCents))),
+        ),
+      ),
+    );
+  }
+  return el('div', { class: 'sig-doc voucher' },
+    el('div', { class: 'sig-doc-title' }, 'Daily Grind Gift Voucher'),
+    el('div', { class: 'sig-voucher-amount' }, money(p.amountCents)),
+    el('div', {}, 'For ', el('strong', {}, p.recipient), p.from ? [' from ', el('strong', {}, p.from)] : null),
+    p.message ? el('blockquote', {}, p.message) : null,
+    el('div', { class: 'sig-doc-meta' }, `Code ${p.code} · valid until ${fmtDate(p.expiresAt)}`),
+  );
+}
+
+/* ------------------------------------------------------------------ */
+/* Verify panel                                                        */
+/* ------------------------------------------------------------------ */
+
+async function runVerify() {
+  const input = $('#sig-verify-input').value;
+  const out = $('#sig-verify-result');
+  out.hidden = false;
+  if (!input.trim()) {
+    out.replaceChildren(el('p', {}, 'Paste a signed token or load a .json file first.'));
+    out.dataset.status = 'invalid';
+    return;
+  }
+  out.replaceChildren(el('p', {}, 'Verifying…'));
+  const r = await core.verifyDocument(input, await trustMap());
+  out.dataset.status = r.status === 'trusted' && r.warnings.length ? 'warn' : r.status;
+
+  const headline = {
+    trusted: r.warnings.length ? '⚠ Authentic, but check the warnings below' : '✔ Authentic & unmodified',
+    untrusted: '⚠ Valid signature from an UNKNOWN signer',
+    invalid: '✖ Verification failed — do not accept',
+  }[r.status];
+
+  const parts = [el('h4', {}, headline)];
+  if (r.status === 'invalid') {
+    parts.push(el('ul', {}, r.errors.map((e) => el('li', {}, e))));
+  } else {
+    parts.push(el('dl', { class: 'sig-dl' },
+      el('dt', {}, 'Signer'), el('dd', {}, r.trusted ? r.signer.label : 'Not in your trusted keys'),
+      el('dt', {}, 'Algorithm'), el('dd', {}, `${r.signer.alg} `, algBadge(r.signer.alg)),
+      el('dt', {}, 'Fingerprint'), el('dd', {}, el('code', { class: 'sig-fp' }, r.signer.fingerprint)),
+    ));
+    if (r.status === 'untrusted') {
+      parts.push(el('p', { class: 'sig-note' },
+        'The document has not been altered since it was signed, but the signing key is not one you trust. '
+        + 'Anyone can create a key pair — only trust it after comparing the fingerprint with the store through a separate channel.'));
+      const pubInfo = { alg: r.signer.alg, kid: r.signer.kid };
+      parts.push(el('button', {
+        type: 'button',
+        class: 'btn-sm',
+        onclick: async () => {
+          const label = prompt('Name this signer (only trust it if you verified the fingerprint):', '');
+          if (label === null) return;
+          await addTrusted({ ...pubInfo, publicKey: core.b64urlToBytes(r.envelope.pub) }, label.trim());
+          runVerify();
+        },
+      }, 'Trust this signer…'));
+    }
+    if (r.warnings.length) parts.push(el('ul', { class: 'sig-warnings' }, r.warnings.map((w) => el('li', {}, w))));
+    parts.push(renderDocument(r.envelope.typ, r.envelope.payload));
+  }
+  out.replaceChildren(...parts);
+}
+
+async function onVerifyFile(e) {
+  const file = e.target.files?.[0];
+  if (!file) return;
+  if (file.size > 64 * 1024) return toast('File is too large to be a Daily Grind document', 'error');
+  $('#sig-verify-input').value = await file.text();
+  e.target.value = '';
+  runVerify();
+}
+
+/* ------------------------------------------------------------------ */
+/* Init                                                                */
+/* ------------------------------------------------------------------ */
+
+async function init() {
+  const root = $('#signing');
+  if (!root) return;
+  if (!globalThis.crypto?.subtle || !globalThis.indexedDB) {
+    root.querySelector('.sig-panels').replaceChildren(
+      el('p', { class: 'sig-warn-text' }, 'Digital signing requires a modern browser served over HTTPS (Web Crypto + IndexedDB).'),
+    );
+    return;
+  }
+
+  // Algorithm picker
+  const select = $('#sig-alg');
+  state.support = await core.detectSupport();
+  for (const [id, info] of Object.entries(core.ALGORITHMS)) {
+    select.append(el('option', { value: id, disabled: !state.support[id] }, info.label + (state.support[id] ? '' : ' — unsupported in this browser')));
+  }
+  select.value = state.support['ML-DSA-65'] ? 'ML-DSA-65' : 'ECDSA-P256';
+
+  $('#sig-keygen-form').addEventListener('submit', onGenerate);
+  $('#sig-trust-form').addEventListener('submit', onImportTrusted);
+
+  // Issue tabs
+  for (const tab of document.querySelectorAll('[data-sig-tab]')) {
+    tab.addEventListener('click', () => {
+      for (const t of document.querySelectorAll('[data-sig-tab]')) t.setAttribute('aria-selected', String(t === tab));
+      $('#sig-receipt-form').hidden = tab.dataset.sigTab !== 'receipt';
+      $('#sig-voucher-form').hidden = tab.dataset.sigTab !== 'voucher';
+    });
+  }
+  buildReceiptItems();
+  $('#sig-receipt-form').addEventListener('submit', (e) => {
+    e.preventDefault();
+    const r = receiptFromForm();
+    if (!r.items.length) return toast('Add at least one item', 'warn');
+    issue('receipt', r);
+  });
+  $('#sig-voucher-form').addEventListener('submit', (e) => {
+    e.preventDefault();
+    issue('voucher', voucherFromForm());
+  });
+
+  // Verify
+  $('#sig-verify-btn').addEventListener('click', runVerify);
+  $('#sig-verify-file').addEventListener('change', onVerifyFile);
+  $('#sig-verify-clear').addEventListener('click', () => {
+    $('#sig-verify-input').value = '';
+    $('#sig-verify-result').hidden = true;
+  });
+
+  try {
+    await reload();
+  } catch (err) {
+    toast(`Could not open key storage: ${err.message}`, 'error');
+  }
+}
+
+init();
