+    /* Seasonal Favorites carousel */
+    .carousel-viewport {
+      max-width: 480px;
+      margin: 20px auto 0;
+      overflow: hidden; /* clips the sliding snapshots in scoped transitions */
+      padding: 4px; /* room for the card shadow */
+    }
+
+    .carousel-controls {
+      display: flex;
+      justify-content: center;
+      align-items: center;
+      gap: 16px;
+      margin-top: 16px;
+    }
+
+    .carousel-btn {
+      font: inherit;
+      background: white;
+      color: var(--primary);
+      border: 2px solid var(--primary);
+      border-radius: 5px;
+      padding: 8px 16px;
+      cursor: pointer;
+      transition: background 0.3s, color 0.3s;
+    }
+
+    .carousel-btn:hover {
+      background: var(--primary);
+      color: white;
+    }
+
+    .carousel-btn:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .carousel-status {
+      min-width: 4em;
+      text-align: center;
+      font-variant-numeric: tabular-nums;
+    }
+
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); opacity: 0; }
+    }
+
+    @keyframes slide-from-right {
+      from { transform: translateX(100%); opacity: 0; }
+    }
+
+    @keyframes slide-to-right {
+      to { transform: translateX(100%); opacity: 0; }
+    }
+
+    @keyframes slide-from-left {
+      from { transform: translateX(-100%); opacity: 0; }
+    }
+
+    /* Scoped transition (element.startViewTransition): the viewport is the scope
+       and participates as "root" inside its own transition. */
+    .carousel-viewport::view-transition-group(root) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+    }
+
+    .carousel-viewport::view-transition-old(root),
+    .carousel-viewport::view-transition-new(root) {
+      animation: 0.4s ease-in-out both;
+    }
+
+    .carousel-viewport:active-view-transition-type(next)::view-transition-old(root) {
+      animation-name: slide-to-left;
+    }
+
+    .carousel-viewport:active-view-transition-type(next)::view-transition-new(root) {
+      animation-name: slide-from-right;
+    }
+
+    .carousel-viewport:active-view-transition-type(previous)::view-transition-old(root) {
+      animation-name: slide-to-right;
+    }
+
+    .carousel-viewport:active-view-transition-type(previous)::view-transition-new(root) {
+      animation-name: slide-from-left;
+    }
+
+    /* Fallback: document-level transition for browsers without element-scoped
