+  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
+    <path d="M12 2.5l2.94 5.96 6.58.96-4.76 4.64 1.12 6.55L12 17.52l-5.88 3.09
+             1.12-6.55L2.48 9.42l6.58-.96L12 2.5z"/>
+  </svg>`;
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
+    :host {
+      --star-size: 2rem;
+      --star-empty: #d7ccc8;
+      --star-filled: #ffab40;
+      --star-hover: #ffcc80;
+      --star-outline: #4e342e;
+      display: inline-flex;
+      align-items: center;
+      gap: 0.75rem;
+      flex-wrap: wrap;
+    }
+    :host([hidden]) { display: none; }
+
+    .stars {
+      display: inline-flex;
+      gap: 0.125rem;
+      border-radius: 6px;
+      outline: 2px solid transparent;
+      outline-offset: 2px;
+    }
+    .stars.user-invalid { outline-color: #c62828; }
+
+    button {
+      all: unset;
+      box-sizing: border-box;
+      inline-size: calc(var(--star-size) + 0.5rem);
+      block-size: calc(var(--star-size) + 0.5rem);
+      display: grid;
+      place-items: center;
+      cursor: pointer;
+      border-radius: 4px;
