diff --git a/src/components/ModalDialog.tsx b/src/components/ModalDialog.tsx
new file mode 100644
index 0000000..2bea683
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,84 @@
+import React, { useEffect, useRef } from 'react';
+
+interface Props {
+    /** id of the heading that names the dialog */
+    labelledBy: string;
+    /** Called after the dialog has closed (Esc, back gesture, backdrop click or close button). */
+    onClose: () => void;
+    children: React.ReactNode;
+}
+
+// Pointer position test (not event.target): the <dialog> itself is the target
+// for clicks on its padding, so a target check would close on those clicks.
+const isOutside = (e: PointerEvent, dialog: HTMLDialogElement) => {
+    const r = dialog.getBoundingClientRect();
+    return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
+};
+
+/**
+ * Native modal <dialog>: the browser provides focus containment, an inert page,
+ * top-layer rendering, ::backdrop, Esc / back-gesture dismissal and focus return
+ * to the invoking control. `closedby="any"` adds light dismiss.
+ *
+ * Mark the initial focus target with `data-autofocus` (defaults to the first
+ * focusable control). Mount it to open it; it calls `onClose` once the native dialog has closed.
+ */
+export default function ModalDialog({ labelledBy, onClose, children }: Props) {
+    const dialogRef = useRef<HTMLDialogElement>(null);
+    const onCloseRef = useRef(onClose);
+    onCloseRef.current = onClose;
+
+    useEffect(() => {
+        const dialog = dialogRef.current;
+        if (!dialog) return;
+        if (!dialog.open) dialog.showModal();
+        // React handles `autoFocus` itself (before the dialog is shown), so the
+        // native [autofocus] dialog focusing step can't see it. Use a data hook.
+        dialog.querySelector<HTMLElement>('[data-autofocus]')?.focus();
+
+        const handleClose = () => onCloseRef.current();
+        dialog.addEventListener('close', handleClose);
+
+        // Light-dismiss fallback where `closedby` is unsupported (e.g. Safari).
+        let pressedOutside = false;
+        const onPointerDown = (e: PointerEvent) => { pressedOutside = isOutside(e, dialog); };
+        const onPointerUp = (e: PointerEvent) => {
+            if (pressedOutside && isOutside(e, dialog)) dialog.close();
+        };
+        const needsFallback = !('closedBy' in HTMLDialogElement.prototype);
+        if (needsFallback) {
+            dialog.addEventListener('pointerdown', onPointerDown);
+            dialog.addEventListener('pointerup', onPointerUp);
+        }
+
+        return () => {
+            dialog.removeEventListener('close', handleClose);
+            if (needsFallback) {
+                dialog.removeEventListener('pointerdown', onPointerDown);
+                dialog.removeEventListener('pointerup', onPointerUp);
+            }
+            if (dialog.open) dialog.close();
+        };
+    }, []);
+
+    return (
+        <dialog
+            ref={dialogRef}
+            closedby="any"
+            aria-labelledby={labelledBy}
+            className="modal-dialog bg-white shadow-xl w-full max-w-2xl mx-auto mt-[15vh] p-0 overflow-visible backdrop:bg-white/30 backdrop:backdrop-blur-sm"
+        >
+            <form method="dialog">
+                <button
+                    aria-label="Close"
+                    className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 transition-transform z-10 cursor-pointer"
+                >
+                    <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+                    </svg>
+                </button>
+            </form>
+            {children}
+        </dialog>
