+    // Fallback placement when CSS anchor positioning is unavailable.
+    function placeMenu(menu) {
+      const t = triggerFor(menu).getBoundingClientRect();
+      const m = menu.getBoundingClientRect();
+      const vw = document.documentElement.clientWidth;
+      const vh = innerHeight;
+      let left, top;
+      if (isSubmenu(menu)) {
+        left = t.right;
+        top = t.top;
+        if (left + m.width > vw) left = t.left - m.width;
+        if (left < 0) { left = t.left + 16; top = t.bottom; } // Below, indented.
+        if (top + m.height > vh) top = Math.max(0, vh - m.height);
+      } else {
+        left = t.left;
+        top = t.bottom + 4;
+        if (left + m.width > vw) left = t.right - m.width;
+        if (top + m.height > vh && t.top - m.height - 4 >= 0) top = t.top - m.height - 4;
+      }
+      menu.style.left = `${Math.max(0, Math.min(left, vw - m.width))}px`;
+      menu.style.top = `${Math.max(0, top)}px`;
+      menu.dataset.placed = '';
+    }
+    if (!hasAnchor) {
+      const reposition = () => menus.filter(isOpen).forEach(placeMenu); // DOM order: parents first.
+      addEventListener('scroll', reposition, { passive: true });
+      addEventListener('resize', reposition);
+    }
+
+    // ----- Triggers -----
+    for (const trigger of triggers) {
+      trigger.addEventListener('pointerdown', () => { pointerTrigger = trigger; });
+
+      trigger.addEventListener('click', event => {
+        const menu = menuFor(trigger);
+        const fromKeyboard = event.detail === 0 && pointerTrigger !== trigger;
+        pointerTrigger = null;
+        const open = isOpen(menu);
+        if (!open && fromKeyboard && !enterOnOpen.has(menu)) enterOnOpen.set(menu, 'first');
+        if (!hasInvokers) {
+          event.preventDefault();
+          if (open) closeAndRestore(menu, { fromPointer: !fromKeyboard });
+          else menu.showPopover({ source: trigger });
+        }
+      });
+
+      // Top-level menu buttons: ArrowDown/ArrowUp open and enter at the first/last item.
+      if (!trigger.closest('.menu')) {
+        trigger.addEventListener('keydown', event => {
+          if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return;
+          event.preventDefault();
+          const menu = menuFor(trigger);
+          const where = event.key === 'ArrowDown' ? 'first' : 'last';
+          if (isOpen(menu)) {
+            const items = itemsOf(groupOf(menu));
+            focusItem(where === 'first' ? items[0] : items.at(-1));
+          } else {
+            enterOnOpen.set(menu, where);
+            trigger.click(); // The invoker stays the only open path.
+          }
+        });
+      }
+    }
+
+    // ----- Menus -----
+    for (const menu of menus) {
+      // Closing menus become inert immediately so they can't take focus during the exit transition.
+      menu.addEventListener('beforetoggle', event => {
+        menu.inert = event.newState === 'closed';
+        if (event.newState === 'closed') delete menu.dataset.placed;
+      });
