+        enterOnOpen.delete(menu);
+        if (where) {
+          const items = itemsOf(groupOf(menu));
+          focusItem(where === 'last' ? items.at(-1) : items[0]);
+        } else if (!isSubmenu(menu) && document.activeElement !== trigger) {
+          // Pointer open: keep focus on the trigger, without a ring, so arrow keys still work.
+          trigger.focus({ focusVisible: false, preventScroll: true });
+        }
+      });
+
+      menu.addEventListener('keydown', event => {
+        lastKey = event.key;
+        const group = groupOf(menu);
+        const item = event.target.closest(ITEM);
+        if (!item || item.closest('[focusgroup]') !== group) return;
+
+        switch (event.key) {
+          case 'Home':
+          case 'End': {
+            const items = itemsOf(group);
+            event.preventDefault();
+            event.stopPropagation();
+            focusItem(event.key === 'Home' ? items[0] : items.at(-1));
+            break;
+          }
+          case 'ArrowRight': {
+            if (!item.hasAttribute('commandfor')) break;
+            event.preventDefault();
+            event.stopPropagation();
+            const submenu = menuFor(item);
+            if (isOpen(submenu)) focusItem(itemsOf(groupOf(submenu))[0]);
+            else { enterOnOpen.set(submenu, 'first'); item.click(); }
+            break;
+          }
+          case 'ArrowLeft':
+            if (!isSubmenu(menu)) break;
+          // falls through
+          case 'Escape':
+            // Close one level only, and restore focus to that level's trigger.
+            event.preventDefault();
+            event.stopPropagation();
+            closeAndRestore(menu);
+            break;
+          case 'Tab': {
+            // Leave the menu system: close everything, then let Tab move on from the root trigger.
+            const root = rootMenuOf(menu);
+            triggerFor(root).focus({ preventScroll: true });
+            root.hidePopover();
+            break;
+          }
+        }
+      });
+    }
+
+    // ----- Item activation -----
+    document.addEventListener('click', event => {
+      const item = event.target.closest(`.menu [focusgroup] ${ITEM}`);
+      if (!item || item.hasAttribute('commandfor')) return;
+      const fromPointer = event.detail !== 0;
+      const root = rootMenuOf(item);
+      const role = item.getAttribute('role');
+      const closeLater = () => setTimeout(() => {
+        if (isOpen(root)) closeAndRestore(root, { fromPointer });
+      }, 300); // Let the changed check mark be seen.
