+        if (!fromPointer && lastKey === ' ') return;
+        closeLater();
+      } else if (role === 'menuitemradio') {
+        const set = item.closest('[role="group"]') ?? item.parentElement;
+        for (const radio of set.querySelectorAll('[role="menuitemradio"]')) {
+          radio.setAttribute('aria-checked', String(radio === item));
+        }
+        onOptionChange(item);
+        closeLater();
+      } else {
+        closeAndRestore(root, { fromPointer });
