+        // Links navigate natively.
+      }
+      lastKey = null;
+    });
+
+    // ----- Pointer: hover follows focus, submenu preview, safe triangle -----
+    document.addEventListener('pointermove', event => {
+      if (event.pointerType === 'touch') return;
+      const item = event.target.closest(`.menu [focusgroup] ${ITEM}`);
+      if (item && document.activeElement !== item) focusItem(item, true);
+    });
+
+    document.addEventListener('pointerover', event => {
+      if (!canHover.matches || event.pointerType === 'touch') return;
+      const item = event.target.closest(`.menu [focusgroup] ${ITEM}`);
