+      for (const sub of group.querySelectorAll(':scope > .menu')) {
+        if (sub !== own && isOpen(sub)) sub.hidePopover();
+      }
+      clearTimeout(hoverTimer);
+      if (own && !isOpen(own)) {
+        hoverTimer = setTimeout(() => {
+          if (item.matches(':hover') && !isOpen(own)) own.showPopover({ source: item });
+        }, 150);
+      }
+    });
+
+    document.addEventListener('pointerout', event => {
+      const item = event.target.closest(`.menu [focusgroup] button[commandfor]`);
+      if (!item || item.contains(event.relatedTarget)) return;
+      startBridge(menuFor(item), event);
+    });
+
+    function startBridge(submenu, event) {
+      if (!canHover.matches || !isOpen(submenu)) return;
+      const rect = submenu.getBoundingClientRect();
+      if (event.clientX >= rect.left && event.clientX <= rect.right) return; // --below: no side edge.
+      const style = submenu.style;
+      style.setProperty('--bridge-edge', `${event.clientX < rect.left ? 0 : rect.width}px`);
+      style.setProperty('--bridge-height', `${rect.height}px`);
+      const update = ({ clientX, clientY, target }) => {
+        if (target !== submenu && submenu.contains(target)) return stop(); // Reached an item.
+        style.setProperty('--bridge-x', `${clientX - rect.left}px`);
+        style.setProperty('--bridge-y', `${clientY - rect.top}px`);
+      };
+      const timer = setTimeout(() => stop(), 300);
+      const stop = () => {
+        clearTimeout(timer);
+        document.removeEventListener('pointermove', update);
+        submenu.removeEventListener('toggle', stop);
+        submenu.removeAttribute('data-bridge');
+      };
+      update(event);
+      submenu.dataset.bridge = '';
+      document.addEventListener('pointermove', update);
+      submenu.addEventListener('toggle', stop, { once: true });
+    }
+
+    // Close every open menu when focus lands outside the menu system.
+    document.addEventListener('focusin', event => {
+      for (const menu of menus) {
+        if (isSubmenu(menu) || !isOpen(menu)) continue;
+        if (!menu.contains(event.target) && event.target !== triggerFor(menu)) menu.hidePopover();
+      }
+    });
+
+    // ---------- App logic: order customizations and commands ----------
+    const announcer = document.getElementById('announcer');
+    const orderCount = document.getElementById('order-count');
+    let toastTimer;
+
+    function announce(message) {
+      announcer.textContent = message;
+      announcer.classList.add('show');
+      clearTimeout(toastTimer);
+      toastTimer = setTimeout(() => announcer.classList.remove('show'), 4000);
+    }
+
+    // Function declarations (hoisted): card setup at the top of the module calls these.
+    function label(item) {
+      return item.textContent.trim();
+    }
+
+    function applyDefaults(card) {
+      const { size, milk, temp } = card.dataset;
+      const extras = card.dataset.extras.split(/\s+/).filter(Boolean);
+      const defaults = { size, milk, temp };
+      for (const item of card.querySelectorAll('[data-option]')) {
+        const { option, value } = item.dataset;
+        const checked = option === 'extras' ? extras.includes(value) : defaults[option] === value;
+        item.setAttribute('aria-checked', String(checked));
+      }
+      updateSummary(card);
+    }
+
+    function describe(card) {
+      const pick = option => card.querySelector(`[data-option="${option}"][aria-checked="true"]`);
+      const size = label(pick('size')).split(' · ')[0];
+      const temp = label(pick('temp'));
+      const milk = pick('milk');
+      const extras = [...card.querySelectorAll('[data-option="extras"][aria-checked="true"]')].map(label);
+      const parts = [size, temp];
+      if (milk.dataset.value !== 'none') parts.push(label(milk));
+      return [...parts, ...extras];
+    }
+
+    function updateSummary(card) {
+      card.querySelector('.selection').textContent = describe(card).join(' · ');
+    }
+
+    function onOptionChange(item) {
+      const card = item.closest('.card');
+      if (card) {
+        updateSummary(card);
+        return;
+      }
+      if (item.dataset.option === 'pickup') announce(`Pickup method set to ${label(item)}.`);
+      if (item.hasAttribute('data-pref')) {
+        announce(`${label(item)}: ${item.getAttribute('aria-checked') === 'true' ? 'on' : 'off'}.`);
+      }
+    }
+
+    function runCommand(item) {
+      const card = item.closest('.card');
+      switch (item.dataset.action) {
+        case 'add-to-order': {
+          orderCount.textContent = Number(orderCount.textContent) + 1;
+          const name = card.querySelector('h3').textContent;
+          announce(`Added ${name} (${describe(card).join(', ')}) to your order.`);
+          break;
+        }
+        case 'reset':
+          applyDefaults(card);
+          announce(`${card.querySelector('h3').textContent} reset to default.`);
+          break;
+        case 'reorder':
+          orderCount.textContent = Number(orderCount.textContent) + 1;
+          announce('Your usual (Medium Maple Oat Latte) was added to your order.');
+          break;
+      }
+    }
+  </script>
+
