+          const menu = item.closest('[role="menu"]');
+          this.items(menu).forEach((other) => {
+            const sub = other !== item && this.submenuOf(other);
+            if (sub && !sub.hidden) this.closeSub(sub);
+          });
+        }
+
+        // Keep menus inside the viewport by flipping horizontally / vertically.
+        position(menu, isSub) {
+          menu.classList.remove('dm-flip-x', 'dm-flip-y');
+          if (getComputedStyle(menu).position !== 'absolute') return;
+          const r = menu.getBoundingClientRect();
+          if (r.right > window.innerWidth - 8) menu.classList.add('dm-flip-x');
+          if (isSub && r.bottom > window.innerHeight - 8) menu.classList.add('dm-flip-y');
+        }
+
+        onKeydown(e) {
+          if (e.target === this.trigger) {
+            if (e.key === 'ArrowDown') { e.preventDefault(); this.open('first'); }
+            else if (e.key === 'ArrowUp') { e.preventDefault(); this.open('last'); }
+            else if (e.key === 'Escape' && this.isOpen) { e.preventDefault(); this.close({ returnFocus: true }); }
+            return;
+          }
+
+          const item = e.target.closest(ITEM_SELECTOR);
+          if (!item || !this.root.contains(item)) return;
+          const menu = item.closest('[role="menu"]');
+          const list = this.items(menu);
+          const idx = list.indexOf(item);
+          const isTop = menu === this.menu;
+
+          switch (e.key) {
+            case 'ArrowDown':
+              e.preventDefault(); this.focusItem(list[(idx + 1) % list.length]); break;
+            case 'ArrowUp':
+              e.preventDefault(); this.focusItem(list[(idx - 1 + list.length) % list.length]); break;
+            case 'Home': case 'PageUp':
+              e.preventDefault(); this.focusItem(list[0]); break;
+            case 'End': case 'PageDown':
+              e.preventDefault(); this.focusItem(list[list.length - 1]); break;
+            case 'ArrowRight':
+              if (this.submenuOf(item)) { e.preventDefault(); this.openSub(item, true); }
+              break;
+            case 'ArrowLeft':
+              if (!isTop) {
+                e.preventDefault();
+                const parent = this.parentItemOf(menu);
+                this.closeSub(menu);
+                this.focusItem(parent);
+              }
+              break;
+            case 'Escape':
+              e.preventDefault();
+              e.stopPropagation();
+              if (isTop) {
+                this.close({ returnFocus: true });
+              } else {
+                const parent = this.parentItemOf(menu);
+                this.closeSub(menu);
+                this.focusItem(parent);
+              }
+              break;
+            case 'Enter': case ' ':
+              e.preventDefault();
+              item.click();
+              break;
+            case 'Tab':
+              // Let focus continue naturally from the trigger's position.
+              this.trigger.focus();
+              this.close();
+              break;
+            default:
+              if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
+                this.typeahead(e.key, list, idx);
+              }
+          }
+        }
+
+        typeahead(char, list, idx) {
+          clearTimeout(this.typeTimer);
+          this.typeBuffer += char.toLowerCase();
+          this.typeTimer = setTimeout(() => { this.typeBuffer = ''; }, 500);
+          const ordered = [...list.slice(idx + 1), ...list.slice(0, idx + 1)];
+          const match = ordered.find((i) => i.textContent.trim().toLowerCase().startsWith(this.typeBuffer))
+            || ordered.find((i) => i.textContent.trim().toLowerCase().startsWith(char.toLowerCase()));
+          this.focusItem(match);
+        }
+
+        onClick(e) {
+          if (e.target.closest('.dm-trigger') === this.trigger) {
+            this.isOpen ? this.close() : this.open('first');
+            return;
+          }
+
+          const item = e.target.closest(ITEM_SELECTOR);
+          if (!item || !this.root.contains(item)) return;
