+          this.emit('dm:select', item);
+          this.close({ returnFocus: !item.hasAttribute('href') });
+        }
+
+        onMouseover(e) {
+          const item = e.target.closest(ITEM_SELECTOR);
+          if (!item || !this.root.contains(item) || item === this.lastHovered) return;
+          this.lastHovered = item;
+          clearTimeout(this.hoverTimer);
+          this.focusItem(item);
+          const hasSub = !!this.submenuOf(item);
+          // Small delay ("hover intent") so diagonal mouse movement doesn't collapse submenus.
+          this.hoverTimer = setTimeout(() => {
+            if (!this.isOpen) return;
+            if (hasSub && window.matchMedia('(min-width: 601px)').matches) this.openSub(item, false);
+            else if (!hasSub) this.closeSiblingSubs(item);
+          }, 150);
+        }
+
+        emit(type, item) {
+          this.root.dispatchEvent(new CustomEvent(type, {
+            bubbles: true,
+            detail: { item, action: item.dataset.action, value: item.dataset.value, checked: item.getAttribute('aria-checked') === 'true' },
+          }));
+        }
+      }
+
+      // ---------- Toast + cart ----------
+      const toastEl = document.getElementById('toast');
+      let toastTimer;
+      const toast = (msg) => {
+        toastEl.textContent = msg;
+        toastEl.classList.add('show');
+        clearTimeout(toastTimer);
+        toastTimer = setTimeout(() => toastEl.classList.remove('show'), 2800);
+      };
+
+      const cartCountEl = document.getElementById('cart-count');
+      let cartCount = 0;
+      const bumpCart = () => {
+        cartCount += 1;
+        cartCountEl.textContent = cartCount;
+        cartCountEl.setAttribute('aria-label', `${cartCount} item${cartCount === 1 ? '' : 's'} in order`);
+      };
+
+      const money = (n) => `$${n.toFixed(2)}`;
+
+      // ---------- Seasonal card customization ----------
+      const template = document.getElementById('customize-template');
+
+      document.querySelectorAll('.card[data-drink]').forEach((card) => {
+        const host = card.querySelector('[data-customize]');
+        host.appendChild(template.content.cloneNode(true));
+        host.querySelector('.dm-menu').setAttribute('aria-label', `Customize ${card.dataset.drink}`);
+        new DropdownMenu(host);
+
+        const base = parseFloat(card.dataset.price);
+        const totalEl = card.querySelector('[data-total]');
+        const summaryEl = card.querySelector('[data-summary]');
+        const detailsHref = card.querySelector('.card-actions > a').getAttribute('href');
+
+        const checkedRadio = (group) => host.querySelector(`[role="menuitemradio"][data-group="${group}"][aria-checked="true"]`);
+        const checkedOptions = () => [...host.querySelectorAll('[role="menuitemcheckbox"][aria-checked="true"]')];
+
+        const applyDefaults = () => {
+          host.querySelectorAll('[role="menuitemcheckbox"]').forEach((c) => c.setAttribute('aria-checked', 'false'));
+          card.dataset.defaults.split(/\s+/).forEach((pair) => {
+            const [key, val] = pair.split(':');
+            if (val === 'on') {
+              host.querySelector(`[data-option="${key}"]`)?.setAttribute('aria-checked', 'true');
+            } else {
+              host.querySelectorAll(`[role="menuitemradio"][data-group="${key}"]`)
+                .forEach((r) => r.setAttribute('aria-checked', String(r.dataset.value === val)));
+            }
+          });
+        };
+
+        const describe = () => {
+          const size = checkedRadio('size');
+          const milk = checkedRadio('milk');
+          const options = checkedOptions();
+          const total = base + [size, milk, ...options]
+            .reduce((sum, el) => sum + (el ? parseFloat(el.dataset.price || 0) : 0), 0);
+          const parts = [size?.dataset.label, milk?.dataset.label, ...options.map((o) => o.dataset.label)].filter(Boolean);
+          return { size, milk, options, total, text: parts.join(' · ') };
+        };
+
+        const render = () => {
+          const d = describe();
+          totalEl.textContent = money(d.total);
+          summaryEl.textContent = d.text;
+          host.querySelector('[data-hint="size"]').textContent = d.size?.dataset.label || '';
+          host.querySelector('[data-hint="milk"]').textContent = d.milk?.dataset.label || 'None';
+          host.querySelector('[data-hint="extras"]').textContent = d.options.length ? `${d.options.length} selected` : '';
+        };
+
+        host.addEventListener('dm:change', render);
+
+        host.addEventListener('dm:select', (e) => {
+          const d = describe();
+          const name = `${d.size?.dataset.label || ''} ${card.dataset.drink}`.trim();
+          switch (e.detail.action) {
+            case 'add':
+              bumpCart();
+              toast(`Added ${name} (${money(d.total)}) to your order.`);
+              break;
+            case 'save':
+              toast(`Saved "${name}" to your favorites.`);
+              break;
+            case 'reset':
+              applyDefaults();
+              render();
+              toast(`${card.dataset.drink} reset to the house recipe.`);
+              break;
+            case 'copy-link': {
+              const url = new URL(detailsHref, location.href).href;
+              (navigator.clipboard ? navigator.clipboard.writeText(url) : Promise.reject())
+                .then(() => toast('Link copied to clipboard.'))
+                .catch(() => toast(url));
+              break;
+            }
+            case 'email': {
+              const url = new URL(detailsHref, location.href).href;
+              location.href = `mailto:?subject=${encodeURIComponent(`Try the ${card.dataset.drink} at The Daily Grind`)}&body=${encodeURIComponent(`${d.text}\n${url}`)}`;
+              break;
+            }
+          }
+        });
+
+        applyDefaults();
+        render();
+      });
+
+      // ---------- Nav menus ----------
+      document.querySelectorAll('nav [data-menu]').forEach((root) => {
+        new DropdownMenu(root);
+        root.addEventListener('dm:change', (e) => {
+          const { item, checked } = e.detail;
+          if (item.getAttribute('role') === 'menuitemradio') {
+            toast(`Default fulfillment set to ${item.textContent.trim().toLowerCase()}.`);
+          } else {
+            toast(`${item.textContent.trim()} ${checked ? 'enabled' : 'disabled'}.`);
+          }
+        });
+      });
+    })();
+  </script>
+
 </body>

 </html>

