+import React, { useState } from 'react';
+
+export default function SignOutButton({ className }: { className?: string }) {
+  const [loading, setLoading] = useState(false);
+
+  const signOut = async () => {
+    setLoading(true);
+    try {
+      await fetch(`${import.meta.env.BASE_URL}api/auth/logout`, { method: 'POST', credentials: 'same-origin' });
+    } finally {
+      window.location.href = import.meta.env.BASE_URL;
+    }
+  };
+
+  return (
+    <button
+      type="button"
+      onClick={signOut}
+      disabled={loading}
+      data-skip-tracking="true"
+      className={
+        className ??
+        'py-2 px-4 rounded-md text-sm font-medium text-gray-700 border border-gray-300 hover:bg-gray-50 disabled:opacity-60'
+      }
+    >
+      {loading ? 'Signing out…' : 'Sign out'}
+    </button>
+  );
+}
