+  /** POST /api/logout */
+  async signOut() {
+    localStorage.removeItem(SESSION_KEY);
+  },
+
+  /** GET /api/passkeys */
+  async listPasskeys() {
+    const db = loadDb();
+    const { session, user } = requireSession(db);
