+# Privacy & security response headers (Netlify / Cloudflare Pages format).
+# The same policy is mirrored for nginx in docs/nginx-privacy-headers.conf.
+# Keep in sync with the <meta http-equiv="Content-Security-Policy"> in index.html.
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self' 'report-sample'; style-src 'self' 'report-sample'; img-src 'self'; font-src 'self'; connect-src 'self'; manifest-src 'self'; form-action 'self'; frame-src 'none'; worker-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; upgrade-insecure-requests; require-trusted-types-for 'script'; trusted-types 'none'; report-to csp
+  Reporting-Endpoints: csp="/api/security-reports"
+  Connection-Allowlist: (response-origin); redirects=allow; report-to=csp
+  Referrer-Policy: strict-origin-when-cross-origin
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), attribution-reporting=(), autoplay=(), bluetooth=(), browsing-topics=(), camera=(), compute-pressure=(), display-capture=(), encrypted-media=(), focus-without-user-activation=(), geolocation=(), gyroscope=(), hid=(), identity-credentials-get=(), idle-detection=(), join-ad-interest-group=(), local-fonts=(), magnetometer=(), microphone=(), midi=(), otp-credentials=(), payment=(), private-aggregation=(), private-state-token-issuance=(), private-state-token-redemption=(), publickey-credentials-get=(self), run-ad-auction=(), screen-wake-lock=(), serial=(), shared-storage=(), shared-storage-select-url=(), storage-access=(), usb=(), window-management=(), xr-spatial-tracking=()
+  Strict-Transport-Security: max-age=31536000; includeSubDomains
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin
+  Cross-Origin-Resource-Policy: same-origin
+  Vary: Sec-Fetch-Dest
+
+# Pages may show signed-in state (account links), so never cache them in shared caches.
+/
+  Cache-Control: private, no-cache
+/index.html
+  Cache-Control: private, no-cache
+
+/account/*
+  Cache-Control: no-store
+
+# Logout is a server endpoint; it must also answer with these headers so the
+# browser drops the session cookie and any client-side storage. "cache" is
+# omitted on purpose: clearing it on a navigation response blocks rendering.
+/logout
+  Clear-Site-Data: "cookies", "storage"
+  Cache-Control: no-store
+
+/images/*
+  Cache-Control: public, max-age=31536000, immutable
+
+/.well-known/gpc.json
+  Content-Type: application/json
+  Cross-Origin-Resource-Policy: cross-origin
+  Access-Control-Allow-Origin: *
