@@ -0,0 +1,38 @@
+# Security & privacy response headers for production static hosting
+# (Netlify / Cloudflare Pages format). Mirror these in any other host/CDN.
+# Local dev (`pnpm start`) sends the CSP + COOP/COEP via statikk flags.
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'self'; manifest-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'; upgrade-insecure-requests
+  Strict-Transport-Security: max-age=63072000; includeSubDomains; preload
+  Referrer-Policy: strict-origin-when-cross-origin
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin
+  Cross-Origin-Embedder-Policy: require-corp
+  Cross-Origin-Resource-Policy: same-origin
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), autoplay=(), browsing-topics=(), camera=(), display-capture=(), encrypted-media=(), geolocation=(), gyroscope=(), hid=(), idle-detection=(), magnetometer=(), microphone=(), midi=(), payment=(self), publickey-credentials-get=(self), serial=(), usb=(), xr-spatial-tracking=()
+  X-DNS-Prefetch-Control: off
+  X-Permitted-Cross-Domain-Policies: none
+  Origin-Agent-Cluster: ?1
+
+# HTML may be personalised for signed-in users: never store in shared caches.
+/
+  Cache-Control: no-store
+/index.html
+  Cache-Control: no-store
+
+# Account pages: no caching anywhere, and wipe client state on logout.
+/account*
+  Cache-Control: no-store
+/logout
+  Cache-Control: no-store
+  Clear-Site-Data: "cache", "cookies", "storage"
+
+# Static first-party assets contain no personal data and can be cached.
+/assets/*
+  Cache-Control: public, max-age=604800
+
+# Don't serve internal tooling/docs from production.
+/scripts/*
+  X-Robots-Tag: noindex
