+  'Permissions-Policy': [
+    'accelerometer=()',
+    'ambient-light-sensor=()',
+    'autoplay=(self)',
+    'bluetooth=()',
+    'browsing-topics=()',
+    'camera=()',
+    'display-capture=()',
+    'geolocation=()',
+    'gyroscope=()',
+    'hid=()',
+    'interest-cohort=()',
+    'magnetometer=()',
+    'microphone=()',
+    'midi=()',
+    'payment=()',
+    'serial=()',
+    'usb=()',
+    'xr-spatial-tracking=()',
+  ].join(', '),
+  'X-Content-Type-Options': 'nosniff',
+};
+
+/** Pages that handle credentials: never cache, never index, never send a referrer. */
+const SENSITIVE_PATHS = [/\/signin\/?$/, /\/signup\/?$/];
