+        // A section is "current" once its top passes just below the sticky nav.
+        var offset = nav.offsetHeight + 20;
+        var current = null;
+
+        sections.forEach(function (section) {
+          if (section.getBoundingClientRect().top - offset <= 0) {
+            current = section.id;
+          }
+        });
