+ * properties (which inherit through the shadow boundary) with built-in
+ * fallbacks, so global selectors like `.card` or `h3` can't leak in.
+ */
+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
+    :host {
+      display: block;
+      contain: content;
+    }
+
+    :host([hidden]) {
+      display: none;
+    }
+
+    .card {
+      position: relative;
+      box-sizing: border-box;
+      height: 100%;
+      background: #fff;
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+      color: var(--text, #3e2723);
+      font: inherit;
+      line-height: 1.6;
+    }
+
+    .badge {
+      position: absolute;
+      top: 12px;
+      right: 12px;
+      background: var(--accent, #ffab40);
+      color: var(--text, #3e2723);
+      font-size: 0.7rem;
+      font-weight: 700;
+      letter-spacing: 0.05em;
+      text-transform: uppercase;
+      padding: 2px 8px;
+      border-radius: 999px;
+    }
+
+    .badge[hidden] {
+      display: none;
+    }
+
+    h3 {
+      margin: 0 0 10px;
+      font-size: 1.17em;
+      color: var(--primary, #4e342e);
+    }
+
+    p {
+      margin: 0;
+    }
+
+    a {
+      display: inline-block;
+      background: var(--primary, #4e342e);
+      color: #fff;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+
+    a:hover,
+    a:focus-visible {
+      background: #3e2723;
+    }
+
+    a:focus-visible {
+      outline: 2px solid var(--accent, #ffab40);
+      outline-offset: 2px;
+    }
+  </style>
+  <article class="card" part="card">
+    <span class="badge" part="badge" hidden></span>
+    <h3 part="heading"></h3>
+    <p part="description"></p>
+    <a part="link"></a>
+  </article>
+`;
