+    form.addEventListener('blur', (e) => syncAria(e.target), true);
+    form.addEventListener('input', (e) => { if (e.target.hasAttribute('aria-invalid')) syncAria(e.target); });
+    form.addEventListener('invalid', (e) => queueMicrotask(() => syncAria(e.target)), true);
+  </script>
+
