+            <label for="rw-email">Email</label>
+            <div class="email-row" id="rw-email-row">
+              <input type="email" id="rw-email" name="email" autocomplete="email" required
+                aria-describedby="rw-email-hint">
+              <span class="verified-badge" aria-hidden="true">&#10003; Verified</span>
+            </div>
+            <p class="hint" id="rw-email-hint" aria-live="polite">
+              Pick your email from your browser's suggestions to confirm it instantly.
+            </p>
+            <button type="button" class="link-btn" id="rw-email-change" hidden>Use a different email</button>
+          </div>
+
+          <div class="field">
+            <label for="rw-drink">Favorite drink <span style="font-weight:normal">(optional)</span></label>
+            <select id="rw-drink" name="favoriteDrink">
+              <option value="">Choose one&hellip;</option>
+              <option value="latte">Latte</option>
+              <option value="espresso">Espresso</option>
+              <option value="cold-brew">Cold Brew</option>
+              <option value="cappuccino">Cappuccino</option>
+              <option value="tea">Tea</option>
+              <option value="other">Something else</option>
+            </select>
+          </div>
+
+          <label class="checkbox">
+            <input type="checkbox" name="marketingOptIn" id="rw-optin">
+            <span>Send me offers and news about new roasts.</span>
+          </label>
+
+          <button type="submit" class="btn" id="rw-submit" disabled>Join Rewards</button>
+          <p class="form-status" id="rw-status" role="status" aria-live="polite"></p>
+        </form>
+      </div>
+    </section>
   </main>

+  <script>
+    (() => {
+      const form = document.getElementById('rewards-form');
+      const emailInput = document.getElementById('rw-email');
+      const emailRow = document.getElementById('rw-email-row');
+      const emailHint = document.getElementById('rw-email-hint');
+      const changeBtn = document.getElementById('rw-email-change');
+      const submitBtn = document.getElementById('rw-submit');
+      const statusEl = document.getElementById('rw-status');
+
+      let verifiedEmail = null;
+      let verifying = false;
+
+      async function postJson(url, body) {
+        const res = await fetch(url, {
+          method: 'POST',
+          credentials: 'same-origin',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify(body || {}),
+        });
+        const data = await res.json().catch(() => ({}));
+        if (!res.ok) throw new Error(data.error || 'Something went wrong. Please try again.');
+        return data;
+      }
+
+      function setHint(text, isError) {
+        emailHint.textContent = text;
+        emailHint.classList.toggle('error', !!isError);
+      }
+
+      function setStatus(text, isError) {
+        statusEl.textContent = text;
+        statusEl.classList.toggle('error', !!isError);
+      }
+
+      function updateSubmit() {
+        submitBtn.disabled = verifying || !verifiedEmail;
+      }
+
+      // Each verification needs a fresh single-use nonce from our server. The browser
+      // binds the email provider's token to this nonce and to our origin.
+      async function armNonce() {
+        try {
+          const { nonce } = await postJson('/api/email-verification/nonce');
+          emailInput.setAttribute('nonce', nonce);
+        } catch (err) {
+          setHint('Email verification is temporarily unavailable. Please reload the page.', true);
+        }
+      }
+
+      function resetVerification() {
+        verifiedEmail = null;
+        emailInput.readOnly = false;
+        emailRow.classList.remove('is-verified');
+        changeBtn.hidden = true;
+        setHint("Pick your email from your browser's suggestions to confirm it instantly.");
+        updateSubmit();
+        armNonce();
+      }
+
+      // Email Verification Protocol: when the user picks an address from autofill, the
+      // browser gets a signed token from the email provider and fires `emailverified`.
+      emailInput.addEventListener('emailverified', async (event) => {
+        const token = event.presentationToken;
+        if (!token) return;
+        verifying = true;
+        updateSubmit();
+        setHint('Confirming your email…');
+        try {
+          const { email } = await postJson('/api/email-verification/verify', { presentationToken: token });
+          verifiedEmail = email;
+          emailInput.value = email;
+          emailInput.readOnly = true;
+          emailRow.classList.add('is-verified');
+          changeBtn.hidden = false;
+          setHint('Your email is confirmed.');
+        } catch (err) {
+          setHint(err.message, true);
+          armNonce();
+        } finally {
+          verifying = false;
+          updateSubmit();
+        }
+      });
+
+      emailInput.addEventListener('input', () => {
+        if (!verifiedEmail) {
+          setHint("Pick your email from your browser's suggestions to confirm it instantly. "
+            + "If none appear, your browser or email provider may not support instant verification yet.");
+        }
+      });
+
+      changeBtn.addEventListener('click', () => {
+        emailInput.value = '';
+        resetVerification();
+        emailInput.focus();
+      });
+
+      form.addEventListener('submit', async (event) => {
+        event.preventDefault();
+        setStatus('');
+        const name = form.elements.name.value.trim();
+        if (!name) {
+          setStatus('Please enter your name.', true);
+          form.elements.name.focus();
+          return;
+        }
+        if (!verifiedEmail) {
+          setStatus('Please confirm your email first.', true);
+          return;
+        }
+        submitBtn.disabled = true;
+        try {
+          const account = await postJson('/api/rewards/register', {
+            name,
+            email: verifiedEmail,
+            favoriteDrink: form.elements.favoriteDrink.value,
+            marketingOptIn: form.elements.marketingOptIn.checked,
+          });
+          const welcome = document.createElement('div');
+          welcome.className = 'welcome';
+          const h = document.createElement('h2');
+          h.textContent = `Welcome, ${account.name}!`;
+          const pts = document.createElement('strong');
+          pts.textContent = `${account.points} points`;
+          const p = document.createElement('p');
+          p.textContent = `Your rewards account for ${account.email} is ready. Show it at the counter to start earning.`;
+          welcome.append(h, pts, p);
+          form.replaceWith(welcome);
+        } catch (err) {
+          setStatus(err.message, true);
+          updateSubmit();
+        }
+      });
+
+      armNonce();
+    })();
+  </script>
+
   <footer>
     <div class="footer-links">
       <a href="/about">Our Story</a> |
