@@ -0,0 +1,47 @@
+import type { CollectionEntry } from 'astro:content';
+
+/** Serializable article summary shared by the JSON API, the search page and agent tools. */
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  tags: string[];
+  readingTime?: number;
+  image: string;
+}
+
+export function toArticleSummary(article: CollectionEntry<'articles'>): ArticleSummary {
+  return {
+    slug: article.id,
+    title: article.data.title,
+    summary: article.data.summary,
+    author: article.data.author,
+    date: article.data.date.toISOString().slice(0, 10),
+    category: article.data.category,
+    tags: article.data.tags ?? [],
+    readingTime: article.data.readingTime,
+    image: article.data.image,
+  };
+}
+
+/** Case-insensitive keyword search: every word must match the title, summary, category, author or a tag. */
+export function searchArticles<T extends Pick<ArticleSummary, 'title' | 'summary' | 'category' | 'author' | 'tags'>>(
+  articles: T[],
+  query: string,
+): T[] {
+  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
+  if (terms.length === 0) return [];
+  return articles.filter((article) => {
+    const haystack = [article.title, article.summary, article.category, article.author, ...article.tags]
+      .join(' ')
+      .toLowerCase();
+    return terms.every((term) => haystack.includes(term));
+  });
+}
+
+export function sortByNewest<T extends Pick<ArticleSummary, 'date'>>(articles: T[]): T[] {
+  return [...articles].sort((a, b) => b.date.localeCompare(a.date));
+}
