+/**
+ * Type declarations for the WebMCP browser API (navigator.modelContext) and
+ * the declarative form attributes used to expose HTML forms as agent tools.
+ * See https://github.com/webmachinelearning/webmcp
+ */
+import 'react';
+
+declare global {
+  interface ModelContextToolResult {
+    content: Array<{ type: 'text'; text: string }>;
+    isError?: boolean;
+  }
+
+  interface ModelContextTool {
+    name: string;
+    description: string;
+    inputSchema?: Record<string, unknown>;
+    annotations?: { readOnlyHint?: boolean };
+    execute: (input: any, client?: unknown) => unknown | Promise<unknown>;
+  }
+
+  interface ModelContext {
+    registerTool(tool: ModelContextTool, options?: { signal?: AbortSignal }): unknown;
+    unregisterTool?(name: string): void;
+  }
+
+  interface Navigator {
+    readonly modelContext?: ModelContext;
+  }
+
+  /** SubmitEvent extensions fired when an agent submits a declarative tool form. */
+  interface AgentSubmitEvent extends SubmitEvent {
+    readonly agentInvoked?: boolean;
+    respondWith?(response: Promise<unknown> | unknown): void;
+  }
+}
+
+declare module 'react' {
+  interface FormHTMLAttributes<T> {
+    toolname?: string;
+    tooldescription?: string;
+    /** Boolean attribute; pass an empty string to enable. */
+    toolautosubmit?: '';
+  }
+  interface InputHTMLAttributes<T> {
+    toolparamtitle?: string;
+    toolparamdescription?: string;
+  }
+  interface SelectHTMLAttributes<T> {
+    toolparamtitle?: string;
+    toolparamdescription?: string;
+  }
+}
+
+export {};
